let warnedProjectMismatch = false;

export function getAdminFirestore(): Firestore {
  if (db) return db;
  const credentials = loadServiceAccountJson();
  const credProject =
    typeof (credentials as { project_id?: string }).project_id === "string"
      ? (credentials as { project_id: string }).project_id.trim()
      : "";
  const webProject = process.env.NEXT_PUBLIC_FIREBASE_PROJECT_ID?.trim();
  if (
    !warnedProjectMismatch &&
    credProject &&
    webProject &&
    credProject !== webProject
  ) {
    warnedProjectMismatch = true;
    console.warn(
      `[Firebase] Service account project_id (${credProject}) differs from NEXT_PUBLIC_FIREBASE_PROJECT_ID (${webProject}). FCM pushes often fail with invalid tokens until both use the same project.`,
    );
  }
  const app = getApps()[0] ?? initializeApp({ credential: cert(credentials) });
  db = getFirestore(app);
  return db;
}

