/**
 * שליחה לרשימת טוקנים; מוחק מסמכי מנוי כשהטוקן בלתי חוקי.
 */
export async function sendFcmToTokens(
  db: Firestore,
  tokens: string[],
  payload: FcmNotificationPayload,
): Promise<{ success: number; failure: number }> {
  const unique = [...new Set(tokens.filter((t) => t.length > 0))];
  if (unique.length === 0) return { success: 0, failure: 0 };

  getAdminFirestore();
  const messaging = getMessaging();

  let success = 0;
  let failure = 0;

  const chunkSize = 500;
  for (let i = 0; i < unique.length; i += chunkSize) {
    const chunk = unique.slice(i, i + chunkSize);
    const res = await messaging.sendEach(
      chunk.map((token) => ({
        token,
        ...webBaseMessage(payload),
      })),
    );

    for (let j = 0; j < res.responses.length; j++) {
      const r = res.responses[j];
      const token = chunk[j];
      if (r.success) {
        success += 1;
        continue;
      }
      failure += 1;
      const code = r.error?.code;
      if (
        code === "messaging/invalid-registration-token" ||
        code === "messaging/registration-token-not-registered" ||
        code === "messaging/invalid-argument"
      ) {
        await deleteSubscriptionDoc(db, subscriptionDocIdForToken(token));
      }
    }
  }

  return { success, failure };
}

