export type FcmSendFailureDetail = {
  code: string;
  /** טקסט שגיאה מ-Firebase (לעיתים ארוך) — לצורך דיבוג */
  message?: string;
};

/**
 * שליחה לרשימת טוקנים; מוחק מסמכי מנוי כשהטוקן בלתי חוקי.
 * `failureDetails` — קודי שגיאה ייחודיים מהשליחה (לדיבוג; ללא טוקן מלא).
 */
export async function sendFcmToTokens(
  db: Firestore,
  tokens: string[],
  payload: FcmNotificationPayload,
): Promise<{ success: number; failure: number; failureDetails: FcmSendFailureDetail[] }> {
  const unique = [...new Set(tokens.filter((t) => t.length > 0))];
  if (unique.length === 0) return { success: 0, failure: 0, failureDetails: [] };

  getAdminFirestore();
  const messaging = getMessaging();

  let success = 0;
  let failure = 0;
  const failureDetails: FcmSendFailureDetail[] =  const pushDetail = (code: string, message?: string) => {
    if (!failureDetails.some((x) => x.code === code)) {
      failureDetails.push(message ? { code, message } : { code });
    }
  };

  const chunkSize = 500;
  for (let i = 0; i < unique.length; i += chunkSize) {
    const chunk = unique.slice(i, i + chunkSize);
    const res = await messaging.sendEach(
      chunk.map((token) => ({
        token,
        ...webBaseMessage(payload),
      })),
    );

    for (let j = 0; j < res.responses.length; j++) {
      const r = res.responses[j];
      const token = chunk[j];
      if (r.success) {
        success += 1;
        continue;
      }
      failure += 1;
      const code = r.error?.code ?? "unknown";
      const msg = r.error?.message;
      pushDetail(code, msg);
      if (
        code === "messaging/invalid-registration-token" ||
        code === "messaging/registration-token-not-registered" ||
        code === "messaging/invalid-argument"
      ) {
        await deleteSubscriptionDoc(db, subscriptionDocIdForToken(token));
      }
    }
  }

  return { success, failure, failureDetails };
}

