async function reportPushSendResult(res: Response): Promise<void> {
  const j = (await res.json().catch(() => ({}))) as {
    error?: string;
    success?: number;
    failure?: number;
    failureDetails?: { code?: string; message?: string }[];
  };
  if (!res.ok) {
    toast.error(j.error ?? `שגיאת PUSH (${res.status})`);
    return;
  }
  const success = j.success ?? 0;
  const failure = j.failure ?? 0;
  const codes =
    Array.isArray(j.failureDetails) && j.failureDetails.length > 0
      ? j.failureDetails
          .map((d) => (typeof d?.code === "string" ? d.code : ""))
          .filter(Boolean)
          .slice(0, 3)
          .join(", ")
      : "";
  if (success === 0 && failure === 0) {
    toast.message(
      "לא נשלחה התראת PUSH — אין מנוי. הלקוח צריך ללחוץ «הפעל התראות» בעמוד ההזמנה (אותו קישור).",
      { duration: 10_000 },
    );
  } else if (success === 0 && failure > 0) {
    const hint =
      codes.includes("messaging/mismatched-credential") ||
      codes.includes("messaging/third-party-auth-error")
        ? " ייתכן שחשבון השירות של השרת (Firebase Admin) לא שייך לאותו פרויקט כמו האתר — בדקו ש־project_id בקובץ המפתח תואם ל־NEXT_PUBLIC_FIREBASE_PROJECT_ID."
        : codes.includes("messaging/sender-id-mismatch")
          ? " טוקן FCM מהפרויקט הלא נכון (Sender ID) — ודאו שהאתר והשרת מוגדרים לאותו פרויקט Firebase."
          : "";
    toast.error(
      `PUSH: השליחה נכשלה (${failure}) — הטוקן שנשמר בשרת לא תקף או לא תואם לשרת. פתחו שוב את עמוד ההזמנה באותו טלפון לרענון רישום.${hint ? `\n${hint}` : ""}${codes ? `\n(קוד FCM: ${codes})` : ""}`,
      { duration: 14_000 },
    );
  }
}

