import { NextResponse } from "next/server";
import { getFirebaseConfig } from "@/lib/firebase/config";

export const runtime = "nodejs";

const FIREBASE_JS = "11.10.0";

/**
 * Service Worker ל-FCM — חייב להשתמש באותה קונפיגורציה כמו `getFirebaseApp()` בלקוח.
 * קובץ סטטי ב-public היה מקובע לפרויקט אחד וגרם לטוקנים לא תקפים כש-NEXT_PUBLIC_FIREBASE_* שונים.
 */
export async function GET() {
  const c = getFirebaseConfig();
  const cfg = JSON.stringify({
    apiKey: c.apiKey,
    authDomain: c.authDomain,
    projectId: c.projectId,
    storageBucket: c.storageBucket,
    messagingSenderId: c.messagingSenderId,
    appId: c.appId,
  });

  const body = `/* Firebase Cloud Messaging — dynamic SW (matches server env NEXT_PUBLIC_FIREBASE_*). */
importScripts("https://www.gstatic.com/firebasejs/${FIREBASE_JS}/firebase-app-compat.js");
importScripts("https://www.gstatic.com/firebasejs/${FIREBASE_JS}/firebase-messaging-compat.js");

firebase.initializeApp(${cfg});

const messaging = firebase.messaging();

const BRAND = "הקוסקוס של מזל";

messaging.onBackgroundMessage((payload) => {
  const rawTitle = payload.notification?.title || BRAND;
  const title = rawTitle.trim().startsWith(BRAND) ? rawTitle : BRAND + " · " + rawTitle;
  const body = payload.notification?.body || "";
  const origin = self.location.origin;
  const icon = origin + "/brand/mazal-app-icon.svg";
  const link = payload.fcmOptions?.link || payload.data?.link || "/";

  return self.registration.showNotification(title, {
    body,
    icon,
    badge: icon,
    data: { url: link },
  });
});

self.addEventListener("notificationclick", (event) => {
  event.notification.close();
  const url = event.notification?.data?.url || "/";
  event.waitUntil(
    self.clients.matchAll({ type: "window", includeUncontrolled: true }).then((clientList) => {
      for (const c of clientList) {
        if (c.url && "focus" in c) return c.focus();
      }
      if (self.clients.openWindow) return self.clients.openWindow(url);
    }),
  );
});
`;

  return new NextResponse(body, {
    status: 200,
    headers: {
      "Content-Type": "application/javascript; charset=utf-8",
      "Cache-Control": "public, max-age=0, must-revalidate",
    },
  });
}

